/* core.js - helpers shared by the three pages. 35_build_pages.py prepends the codec generated by
   30_dashboard_common.js_decoder() (B64, varints, unzig, qualValues, clusterId, islandId) and the
   META object, then inlines this file. Nothing here touches a payload directly. */
"use strict";
const $ = id => document.getElementById(id);
const esc = s => String(s == null ? "" : s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const fmt = n => (n == null || n !== n) ? "" : (+n).toLocaleString("en-US");
const f1 = (n, d) => (n == null || n < 0) ? "" : (+n).toFixed(d == null ? 1 : d);
const pct = (permille, d) => permille == null || permille < 0 ? "" : (permille / 10).toFixed(d == null ? 1 : d) + "%";
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

/* dictionary lookup: dicts[key][index], "" for -1 */
const dict = (dicts, key, idx) => (idx == null || idx < 0) ? "" : ((dicts[key] || [])[idx] ?? "");
/* positional record -> object, from a field list */
function fieldIndex(fields){ const o = {}; fields.forEach((f, i) => o[f] = i); return o; }

/* the query string carries page state, so links between the pages can point at one record */
const QS = {
  get(k){ return new URLSearchParams(location.search).get(k); },
  set(obj){ const p = new URLSearchParams(location.search);
    for(const k in obj){ if(obj[k] == null || obj[k] === "") p.delete(k); else p.set(k, obj[k]); }
    const s = p.toString(); history.replaceState(null, "", s ? "?" + s : location.pathname); }
};
const link = {
  cluster: n => `clusters.html?cluster=${clusterId(n)}`,
  island: n => `islands.html?island=${islandId(n)}`,
  islandsOf: n => `islands.html?cluster=${clusterId(n)}`,
};
/* accepts CFR-000010, cfr10, 10 */
function parseClusterArg(s){ if(!s) return null; const m = /(\d+)\s*$/.exec(String(s)); return m ? +m[1] : null; }
function parseIslandArg(s){ if(!s) return null; const m = /(\d+)\s*$/.exec(String(s)); return m ? +m[1] : null; }

/* gene roles - the order genemaps.json gives them, and their treatment (WORKPLAN_dashboard.md s5) */
const ROLE_STYLE = {
  amr_anchor_mobile: {fill:"var(--r-mobile-f)", stroke:"var(--r-mobile-s)", sw:1.5, label:"acquired resistance", colour:"coral"},
  amr_anchor_core:   {fill:"var(--r-core-f)",   stroke:"var(--r-core-s)",   sw:1,   label:"chromosomal resistance", colour:"coral"},
  amr_anchor_point:  {fill:"none",              stroke:"var(--r-point-s)",  sw:1.5, dot:true, label:"point-mutation target", colour:"coral"},
  stress:            {fill:"var(--r-stress-f)", stroke:"var(--r-stress-s)", sw:1,   label:"stress", colour:"teal"},
  virulence:         {fill:"var(--r-vir-f)",    stroke:"var(--r-vir-s)",    sw:1,   label:"virulence", colour:"purple"},
  mge:               {fill:"var(--r-mge-f)",    stroke:"var(--r-mge-s)",    sw:1,   label:"mobile element", colour:"mustard"},
  mge_pseudo:        {fill:"var(--r-mge-ps-f)", stroke:"var(--r-mge-s)",    sw:1,   dash:true, label:"mobile element, pseudogene", colour:"mustard"},
  other:             {fill:"var(--r-other-f)",  stroke:"var(--r-other-s)",  sw:1,   label:"other", colour:""},
  hypothetical:      {fill:"var(--r-other-f)",  stroke:"var(--r-other-s)",  sw:1,   label:"hypothetical", colour:""},
};
/* the short chip wording of each role, matching the legend: "acquired" is an AMR anchor in the
   mobile part of the pangenome, not a mobile element - that is "mobile element", in mustard */
const ROLE_SHORT = {amr_anchor_mobile:"acquired resistance", amr_anchor_core:"chromosomal resistance", amr_anchor_point:"point mutation", stress:"stress", virulence:"virulence", mge:"mobile element", other:"other", hypothetical:"hypothetical"};
const roleChip = (role, pseudo) => `<span class="chip ${(ROLE_STYLE[role] || ROLE_STYLE.other).colour}">${esc(ROLE_SHORT[role] || role)}${pseudo && role === "mge" ? " · pseudo" : ""}</span>`;
const ANALYSED_ROLES = new Set(["amr_anchor_mobile", "amr_anchor_core", "amr_anchor_point", "stress", "virulence"]);
const SET_NAME = ["amr", "stress", "virulence"], SET_COLOUR = ["coral", "teal", "purple"];
const TIER_COLOUR = {CORE_AMR:"coral", SOFTCORE_AMR:"coral", SHELL_AMR:"coral", MOBILE_AMR:"coral", POINT_ONLY:"coral", NOT_AN_ANCHOR:""};
const PLDDT_BUCKETS = [[50, "var(--q-lo)", "coral"], [70, "var(--q-mid)", "mustard"], [90, "var(--q-hi)", "teal"], [101, "var(--q-top)", "fg"]];
function plddtColour(v){ for(const b of PLDDT_BUCKETS) if(v < b[0]) return b[1]; return "var(--q-top)"; }
function plddtClass(v){ for(const b of PLDDT_BUCKETS) if(v < b[0]) return b[2]; return "fg"; }
/* variation buckets: none, low, moderate, high - captioned wherever drawn */
const VAR_BUCKETS = [[0.5, "var(--fg-dim)", "none"], [5, "var(--c-teal)", "under 5% of lineages"], [20, "var(--c-mustard)", "5-20%"], [101, "var(--c-coral)", "over 20%"]];
function varColour(v){ for(const b of VAR_BUCKETS) if(v < b[0]) return b[1]; return "var(--c-coral)"; }

/* a small gene arrow for legends */
function legendArrow(style){
  const s = ROLE_STYLE[style];
  return `<svg viewBox="0 0 22 12"><polygon points="1,1 15,1 21,6 15,11 1,11" fill="${s.fill}" stroke="${s.stroke}" stroke-width="${s.sw}"${s.dash?' stroke-dasharray="2 2"':''}/>${s.dot?'<circle cx="9" cy="6" r="1.6" fill="'+s.stroke+'"/>':''}</svg>`;
}
function legendHTML(keys){
  return (keys || Object.keys(ROLE_STYLE)).map(k => `<span>${legendArrow(k)}${esc(ROLE_STYLE[k].label)}</span>`).join("");
}

/* tabs: buttons with data-tab inside .tabs, panes with data-pane; state kept in ?tab= */
function wireTabs(onChange){
  const btns = [...document.querySelectorAll(".tabs button[data-tab]")];
  const go = name => {
    btns.forEach(b => b.setAttribute("aria-selected", String(b.dataset.tab === name)));
    document.querySelectorAll("[data-pane]").forEach(p => p.dataset.active = String(p.dataset.pane === name));
    QS.set({tab: name === btns[0].dataset.tab ? null : name});
    if(onChange) onChange(name);
  };
  btns.forEach((b, i) => {
    b.onclick = () => go(b.dataset.tab);
    b.onkeydown = e => { if(e.key === "ArrowRight" || e.key === "ArrowLeft"){
      const j = (i + (e.key === "ArrowRight" ? 1 : btns.length - 1)) % btns.length; btns[j].focus(); go(btns[j].dataset.tab); } };
  });
  const want = QS.get("tab");
  go(btns.some(b => b.dataset.tab === want) ? want : btns[0].dataset.tab);
  return go;
}
/* segmented toggle: one pressed button inside a .seg; returns the setter */
function wireSeg(el, onChange, initial){
  const btns = [...el.querySelectorAll("button")];
  const set = v => { btns.forEach(b => b.setAttribute("aria-pressed", String(b.dataset.v === v))); onChange(v); };
  btns.forEach(b => b.onclick = () => set(b.dataset.v));
  if(initial != null) btns.forEach(b => b.setAttribute("aria-pressed", String(b.dataset.v === initial)));
  return set;
}
function debounce(fn, ms){ let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms || 120); }; }
function opts(sel, list, allLabel){
  sel.innerHTML = `<option value="">${esc(allLabel)}</option>` + list.map(([v, l]) => `<option value="${esc(v)}">${esc(l)}</option>`).join("");
}
/* tooltip anchored to the pointer, kept on screen */
function showTip(tip, e, html){
  tip.innerHTML = html; tip.style.display = "block";
  const r = tip.getBoundingClientRect();
  let x = e.clientX + 14, y = e.clientY + 14;
  if(x + r.width > innerWidth - 8) x = e.clientX - 14 - r.width;
  if(y + r.height > innerHeight - 8) y = e.clientY - 14 - r.height;
  tip.style.left = Math.max(4, x + scrollX) + "px"; tip.style.top = Math.max(4, y + scrollY) + "px";
}
function hideTip(tip){ tip.style.display = "none"; }
/* bar list: rows [label, value, colourClass?, onclickValue?] */
function barsHTML(rows, max, opt){
  opt = opt || {};
  const mx = max || Math.max(1, ...rows.map(r => r[1]));
  return `<div class="bars">` + rows.map(r => {
    const lab = opt.click ? `<button class="bl" data-v="${esc(r[3] ?? r[0])}" title="${esc(r[0])}">${esc(r[0])}</button>` : `<span class="bl" title="${esc(r[0])}">${esc(r[0])}</span>`;
    return `${lab}<span class="bv ${r[2] || ""}"><i style="width:${(100 * r[1] / mx).toFixed(2)}%"></i></span><span class="bn">${opt.format ? opt.format(r[1]) : fmt(r[1])}</span>`;
  }).join("") + `</div>`;
}
function copyText(t, btn){ try{ navigator.clipboard.writeText(t); if(btn){ const o = btn.textContent; btn.textContent = "copied"; setTimeout(() => btn.textContent = o, 900); } }catch(e){} }

/* theme: dark (the brand book's) by default, light on request. The choice is kept in localStorage,
   shared by the three pages; the head script 35_build_pages.py inlines applies it before first paint,
   so a light page never flashes dark. Storage can be blocked on file://, so every access is guarded
   and the page still works, just without remembering. Pages that paint with resolved colours (the
   structure canvas) listen for the "themechange" event and redraw. */
const THEME_KEY = "amr-dashboard-theme";
const THEME_ICON = {
  light: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M5.3 18.7l1.6-1.6M17.1 6.9l1.6-1.6"/></svg>',
  dark: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5a8.5 8.5 0 1 0 10.7 10.7z"/></svg>',
};
const currentTheme = () => document.documentElement.dataset.theme === "light" ? "light" : "dark";
function setTheme(t, save){
  if(t === "light") document.documentElement.dataset.theme = "light"; else delete document.documentElement.dataset.theme;
  if(save){ try{ localStorage.setItem(THEME_KEY, t); }catch(e){} }
  const b = document.querySelector(".themebtn");
  if(b){ const to = t === "light" ? "dark" : "light";
    b.innerHTML = THEME_ICON[to]; b.title = `switch to ${to} theme`; b.setAttribute("aria-label", `switch to ${to} theme`); }
  document.dispatchEvent(new CustomEvent("themechange", {detail: t}));
}
(function mountThemeButton(){
  const nav = document.querySelector(".nav");
  if(!nav) return;
  const b = document.createElement("button");
  b.type = "button"; b.className = "themebtn";
  b.onclick = () => setTheme(currentTheme() === "light" ? "dark" : "light", true);
  nav.appendChild(b);
  setTheme(currentTheme(), false);
})();
